/** The public local-model catalog: its types, its version, and the check that a document
 * read from the network or from disk is one. The catalog is DATA that ClikDeploy publishes
 * (signed, see catalog-signature.ts); the fit/speed decision runs on the user's machine
 * over it. Nothing about the machine is part of this schema or sent anywhere.
 *
 * Every file is pinned: the Hugging Face commit it is fetched from, its size, and its
 * SHA-256 as Hugging Face's LFS metadata records it. A download whose hash differs is
 * refused, so a repo that is force-pushed later cannot swap the weights under a user. */

export interface CatalogFile {
  repo: string;
  /** Hugging Face commit sha the file is fetched at. */
  revision: string;
  file: string;
  sizeBytes: number;
  sha256: string;
}

/** Attention layers' KV-cache shape, per token. Sliding-window layers keep
 * only `window` tokens, so they cost a fixed amount whatever the context. */
export interface KvGeometry {
  layers: number;
  kvHeads: number;
  keyLength: number;
  valueLength: number;
  sliding?: { layers: number; kvHeads: number; keyLength: number; valueLength: number; window: number };
  /** Recurrent (linear-attention) state per sequence, f32, for hybrids:
   * llama.cpp keeps one live copy plus a checkpoint every 8K tokens. */
  recurrentStateBytes?: number;
}

export interface CatalogModel {
  id: string;
  label: string;
  weights: CatalogFile;
  /** Vision projector; loaded only when a caller asks for images. */
  projector?: CatalogFile;
  architecture: string;
  totalParamsB: number;
  /** Parameters read per token: all of them for a dense model, the routed
   * experts' share for a mixture of experts. Speed follows this. */
  activeParamsB: number;
  quantization: string;
  defaultContext: number;
  maxContext: number;
  license: 'apache-2.0' | 'mit';
  kv: KvGeometry;
  /** Rough rank for agentic coding, 0-100, used only to order models that
   * all meet the speed bar. A higher-precision build of the same model
   * scores a little above its Q4_K_M, kept below the gap to the next model,
   * so a quant never outranks a stronger model. */
  quality: number;
  qualityNote: string;
  /** Derived on the user's machine from a remote GGUF header, never published. */
  discovered?: boolean;
  /** Weight bytes actually read per generated token, from tensor metadata. */
  activeWeightBytes?: number;
}

/** Bumped when the shape of a catalog changes in a way an older reader cannot understand. */
export const LOCAL_CATALOG_SCHEMA = 1;

export interface LocalCatalog {
  schema: typeof LOCAL_CATALOG_SCHEMA;
  /** Increases with every published change; a reader keeps the highest version it has verified. */
  version: number;
  /** ISO time the version was published. */
  publishedAt: string;
  models: CatalogModel[];
}

const SHA256 = /^[0-9a-f]{64}$/;
const COMMIT = /^[0-9a-f]{40}$/;

function fail(path: string, expected: string): never {
  throw new Error(`Local model catalog: ${path} must be ${expected}.`);
}

function record(value: unknown, path: string): Record<string, unknown> {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) fail(path, 'an object');
  return value as Record<string, unknown>;
}

function text(value: unknown, path: string): string {
  if (typeof value !== 'string' || !value) fail(path, 'a non-empty string');
  return value as string;
}

function positive(value: unknown, path: string): number {
  if (typeof value !== 'number' || !Number.isFinite(value) || value <= 0) fail(path, 'a positive number');
  return value as number;
}

function file(value: unknown, path: string): CatalogFile {
  const item = record(value, path);
  const sha256 = text(item.sha256, `${path}.sha256`);
  const revision = text(item.revision, `${path}.revision`);
  if (!SHA256.test(sha256)) fail(`${path}.sha256`, 'a lowercase hex SHA-256');
  if (!COMMIT.test(revision)) fail(`${path}.revision`, 'a 40-character commit sha');
  return { repo: text(item.repo, `${path}.repo`), revision, file: text(item.file, `${path}.file`), sizeBytes: positive(item.sizeBytes, `${path}.sizeBytes`), sha256 };
}

function kv(value: unknown, path: string): KvGeometry {
  const item = record(value, path);
  const geometry: KvGeometry = {
    layers: positive(item.layers, `${path}.layers`), kvHeads: positive(item.kvHeads, `${path}.kvHeads`),
    keyLength: positive(item.keyLength, `${path}.keyLength`), valueLength: positive(item.valueLength, `${path}.valueLength`),
  };
  if (item.sliding !== undefined) {
    const sliding = record(item.sliding, `${path}.sliding`);
    geometry.sliding = {
      layers: positive(sliding.layers, `${path}.sliding.layers`), kvHeads: positive(sliding.kvHeads, `${path}.sliding.kvHeads`),
      keyLength: positive(sliding.keyLength, `${path}.sliding.keyLength`), valueLength: positive(sliding.valueLength, `${path}.sliding.valueLength`),
      window: positive(sliding.window, `${path}.sliding.window`),
    };
  }
  if (item.recurrentStateBytes !== undefined) geometry.recurrentStateBytes = positive(item.recurrentStateBytes, `${path}.recurrentStateBytes`);
  return geometry;
}

function model(value: unknown, path: string): CatalogModel {
  const item = record(value, path);
  if (item.license !== 'apache-2.0' && item.license !== 'mit') fail(`${path}.license`, "'apache-2.0' or 'mit'");
  const result: CatalogModel = {
    id: text(item.id, `${path}.id`), label: text(item.label, `${path}.label`),
    weights: file(item.weights, `${path}.weights`),
    architecture: text(item.architecture, `${path}.architecture`),
    totalParamsB: positive(item.totalParamsB, `${path}.totalParamsB`), activeParamsB: positive(item.activeParamsB, `${path}.activeParamsB`),
    quantization: text(item.quantization, `${path}.quantization`),
    defaultContext: positive(item.defaultContext, `${path}.defaultContext`), maxContext: positive(item.maxContext, `${path}.maxContext`),
    license: item.license, kv: kv(item.kv, `${path}.kv`),
    quality: positive(item.quality, `${path}.quality`), qualityNote: text(item.qualityNote, `${path}.qualityNote`),
  };
  if (item.projector !== undefined) result.projector = file(item.projector, `${path}.projector`);
  if (item.activeWeightBytes !== undefined) result.activeWeightBytes = positive(item.activeWeightBytes, `${path}.activeWeightBytes`);
  return result;
}

/** A catalog document read from outside: throws unless every field a reader depends on is
 * present and well formed. Unknown extra fields are dropped, so a newer publisher adding a
 * field does not break an older reader (a changed meaning bumps `schema` instead). */
export function parseLocalCatalog(value: unknown): LocalCatalog {
  const item = record(value, 'catalog');
  if (item.schema !== LOCAL_CATALOG_SCHEMA) fail('schema', `${LOCAL_CATALOG_SCHEMA}`);
  const version = positive(item.version, 'version');
  if (!Number.isInteger(version)) fail('version', 'an integer');
  const publishedAt = text(item.publishedAt, 'publishedAt');
  if (Number.isNaN(Date.parse(publishedAt))) fail('publishedAt', 'an ISO time');
  if (!Array.isArray(item.models) || !item.models.length) fail('models', 'a non-empty array');
  const models = (item.models as unknown[]).map((entry, index) => model(entry, `models[${index}]`));
  const ids = new Set<string>();
  for (const entry of models) {
    if (ids.has(entry.id)) fail('models', `unique by id (${entry.id} repeats)`);
    ids.add(entry.id);
  }
  return { schema: LOCAL_CATALOG_SCHEMA, version, publishedAt, models };
}
